<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Search, Connection, Right } from '@element-plus/icons-vue'
import { api } from '../api'
import { state, refresh, vehicle, branch, labels, localTime, dateText } from '../store'
import FormDialog from '../components/FormDialog.vue'
import StatusTag from '../components/StatusTag.vue'
import VehicleIdentity from '../components/VehicleIdentity.vue'
const open = ref(false), busy = ref(false), page = ref(1), detail = ref(null), query = reactive({ search: '', status: '' })
const filtered = computed(() => state.dispatch.filter(task => (!query.status || query.status === task.status) && (!query.search || `${vehicle(task.vehicle_id).plate}${task.assignee}`.includes(query.search))))
watch(query, () => page.value = 1)
const fields = computed(() => [{ key: 'vehicle_id', label: '调度车辆', type: 'select', wide: true, options: state.vehicles.filter(car => car.status === 'AVAILABLE').map(car => ({ label: `${car.plate} · ${car.model} / ${branch(car.branch_id).name}`, value: car.id })) }, { key: 'to_branch', label: '目标门店', type: 'select', options: form => state.branches.filter(item => item.id !== vehicle(form.vehicle_id).branch_id).map(item => ({ label: item.name, value: item.id })) }, { key: 'assignee', label: '调度负责人' }, { key: 'planned_start', label: '计划出发时间', type: 'datetime' }, { key: 'planned_end', label: '计划到达时间', type: 'datetime' }, { key: 'notes', label: '调度说明', type: 'textarea', required: false, wide: true, maxlength: 500 }])
const initial = computed(() => ({ planned_start: localTime(new Date(Date.now() + 60000)), planned_end: localTime(new Date(Date.now() + 3660000)), assignee: state.user.name }))
async function save(data) { busy.value = true; try { await api.post('/dispatch', data); open.value = false; await refresh(); ElMessage.success('调度任务已创建') } catch {} finally { busy.value = false } }
async function action(task, type) { try { await ElMessageBox.confirm(`确认${{ start: '开始调度', complete: '车辆已到达目标门店', cancel: '取消任务' }[type]}？`, '调度操作'); busy.value = true; await api.post(`/dispatch/${task.id}/${type}`); await refresh(); ElMessage.success('调度状态已更新') } catch {} finally { busy.value = false } }
</script>
<template>
  <section class="branch-board">
    <div class="branch-board-intro"><span>跨店调度</span><h2>门店运力</h2><p><b class="dispatch-metric">{{ state.dispatch.filter(task => task.status === 'IN_PROGRESS').length }}</b> 项调拨在途<br><b class="dispatch-metric">{{ state.dispatch.filter(task => task.status === 'PENDING').length }}</b> 项等待发车</p><router-link to="/vehicles">全部车辆 <el-icon><Right /></el-icon></router-link></div>
    <div class="branch-grid"><section v-for="item in state.branches" :key="item.id" class="branch-card"><div class="branch-location"><h3>{{ item.name }}</h3><p>{{ item.address }}</p></div><div class="branch-count"><strong>{{ state.vehicles.filter(car => car.branch_id === item.id && car.status === 'AVAILABLE').length }}<small>/ {{ state.vehicles.filter(car => car.branch_id === item.id).length }}</small></strong><span>辆当前可用</span></div><router-link class="branch-available-link" :to="`/vehicles?branch=${item.id}&status=AVAILABLE`">查看可用车辆 <el-icon><Right /></el-icon></router-link></section></div>
  </section>
  <section class="panel listing-panel"><div class="filter-bar"><el-input v-model="query.search" :prefix-icon="Search" placeholder="搜索车牌、负责人" clearable class="search-input"/><el-select v-model="query.status" placeholder="全部任务状态" clearable><el-option v-for="status in ['PENDING', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED']" :key="status" :label="labels[status]" :value="status"/></el-select><div class="filter-spacer"></div><el-button type="primary" :icon="Plus" @click="open = true">新建调度</el-button></div><div class="listing-caption"><span>调度任务 <small>{{ filtered.length }} 项</small></span><span>人工派单 · 执行前校验预约冲突</span></div><el-table :data="filtered.slice((page - 1) * 10, page * 10)"><el-table-column label="车辆" min-width="245"><template #default="{ row }"><VehicleIdentity :vehicle="vehicle(row.vehicle_id)"/></template></el-table-column><el-table-column label="调度路线" min-width="185"><template #default="{ row }"><span>{{ branch(row.from_branch).name }}</span><small class="cell-sub">→ {{ branch(row.to_branch).name }}</small></template></el-table-column><el-table-column label="计划时间" min-width="155"><template #default="{ row }">{{ dateText(row.planned_start) }}<small class="cell-sub">至 {{ dateText(row.planned_end) }}</small></template></el-table-column><el-table-column prop="assignee" label="负责人" width="100"/><el-table-column label="状态" width="110"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="操作" min-width="165" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="detail = row">详情</el-button><template v-if="row.status === 'PENDING'"><el-button link type="primary" :disabled="busy" @click="action(row, 'start')">开始</el-button><el-button link type="danger" :disabled="busy" @click="action(row, 'cancel')">取消</el-button></template><el-button v-if="row.status === 'IN_PROGRESS'" link type="primary" :disabled="busy" @click="action(row, 'complete')">确认到达</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ filtered.length }} 项调度任务</span><el-pagination v-model:current-page="page" :page-size="10" :total="filtered.length" layout="prev, pager, next"/></div></section>
  <FormDialog v-model="open" title="新建车辆调度任务" :fields="fields" :initial="initial" :busy="busy" @submit="save"/>
  <el-dialog :model-value="!!detail" @close="detail = null" title="调度任务详情" width="600px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="车辆"><VehicleIdentity :vehicle="vehicle(detail.vehicle_id)"/></el-descriptions-item><el-descriptions-item label="路线">{{ branch(detail.from_branch).name }} → {{ branch(detail.to_branch).name }}</el-descriptions-item><el-descriptions-item label="负责人">{{ detail.assignee }}</el-descriptions-item><el-descriptions-item label="实际出发">{{ dateText(detail.actual_start) }}</el-descriptions-item><el-descriptions-item label="实际到达">{{ dateText(detail.actual_end) }}</el-descriptions-item><el-descriptions-item label="说明">{{ detail.notes || '无' }}</el-descriptions-item></el-descriptions></el-dialog>
</template>
